mapper.sql:
WITH movie_agg AS (
    SELECT m.movie_id,
           m.title,
           m.release_year,
           COUNT(r.rating_id) AS rating_count,
           AVG(r.score)       AS avg_score
    FROM dim_movie m
    LEFT JOIN fact_rating r
           ON r.movie_id = m.movie_id
          AND r.rated_date >= #{from}
          AND r.rated_date <= #{to}
    WHERE 1 = 1

        AND EXISTS (
            SELECT 1
            FROM rel_movie_genre rg
            JOIN dim_genre g ON g.genre_id = rg.genre_id
            WHERE rg.movie_id = m.movie_id
              AND g.genre_name IN
            #{gn}
        )


        AND m.release_year >= #{q.yearFrom}


        AND m.release_year <= #{q.yearTo}


        AND m.title LIKE CONCAT('%', #{q.keyword}, '%')

    GROUP BY m.movie_id, m.title, m.release_year
    HAVING 1 = 1

        AND AVG(r.score) >= #{q.ratingFrom}


        AND AVG(r.score) <= #{q.ratingTo}

)

mapper.select:

SELECT COUNT(*)
FROM fact_rating r
JOIN movie_agg ma ON ma.movie_id = r.movie_id
WHERE r.rated_date >= #{from}
  AND r.rated_date <= #{to}


SELECT COUNT(DISTINCT r.user_id)
FROM fact_rating r
JOIN movie_agg ma ON ma.movie_id = r.movie_id
WHERE r.rated_date >= #{from}
  AND r.rated_date <= #{to}
